('advai_joke', 'My favourite stat is fewer repair bills.', 0, 0, '', '', '', '', '', '', '', ''),
('advai_joke', 'Every road leads somewhere. Usually another quest giver.', 0, 0, '', '', '', '', '', '', '', ''),
('advai_joke', 'One quick quest is how entire evenings disappear.', 0, 0, '', '', '', '', '', '', '', ''),
